window.EL_CAPSULES = window.EL_CAPSULES || {};
Object.assign(window.EL_CAPSULES, {
  "p4:Oct:1": {"title": "Los primeros habitantes de Hispania", "steps": [{"type": "hook", "kicker": "Antes de Roma", "h": "¿Quién vivía en España antes de que llegaran los romanos?", "scenario": "Imagina que excavas en tu jardín y encuentras una moneda antiguísima, mucho antes de que existieran los romanos en España.", "body": "Mucho antes de la llegada de Roma, la península ibérica ya estaba llena de <b>pueblos distintos</b>, cada uno con su lengua, sus costumbres y sus dioses. Esta semana vas a conocer a los verdaderos protagonistas de la Hispania más antigua."}, {"type": "theory", "kicker": "Un mapa de pueblos", "h": "Iberos, celtas, fenicios y griegos", "body": "Los <b>iberos</b> vivían en el este y el sur, en pueblos fortificados y con una escritura propia. Los <b>celtas</b> ocupaban el norte y el oeste, dedicados a la ganadería y organizados en clanes. Los <b>fenicios</b>, grandes comerciantes venidos del Mediterráneo oriental, fundaron colonias en la costa sur, como Cádiz. Los <b>griegos</b> se instalaron en la costa este, en lugares como Empúries, y trajeron el comercio y el alfabeto.", "diagram": "<b>IBEROS</b>: este y sur <br><b>CELTAS</b>: norte y oeste <br><b>FENICIOS</b>: costa sur (comercio) <br><b>GRIEGOS</b>: costa este (colonias)"}, {"type": "quiz", "kicker": "Comprueba tu mapa", "h": "¿Dónde se instalaron principalmente los fenicios?", "q": "¿En qué zona de la península fundaron sus colonias los fenicios?", "opts": [{"t": "En la costa sur, como Cádiz", "ok": true}, {"t": "En el centro de la meseta", "ok": false}, {"t": "En el norte, junto a los celtas", "ok": false}, {"t": "En las montañas del interior", "ok": false}], "okMsg": "¡Correcto! Los fenicios, grandes navegantes, buscaban costas para comerciar.", "noMsg": "Casi. Recuerda que los fenicios eran comerciantes que llegaban en barco, por eso se instalaron en la costa sur."}, {"type": "reflect", "kicker": "Tu mapa de pueblos", "h": "Dibuja la Hispania anterior a Roma", "body": "Vas a crear tu propio mapa de los pueblos prerromanos, situando cada uno en su lugar correcto.", "prompt": "Dibuja o calca un mapa sencillo de la península ibérica. Ubica y colorea de forma diferente las zonas de los <b>iberos</b>, <b>celtas</b>, <b>fenicios</b> y <b>griegos</b>, y escribe el nombre de cada pueblo junto a su territorio."}]},
  "p4:Oct:2": {"title": "Las huellas de Roma en piedra", "steps": [{"type": "hook", "kicker": "Piedras que hablan", "h": "¿Sabías que hay puentes y acueductos romanos que todavía se usan hoy?", "scenario": "Un turista pasea por Segovia y se sorprende al ver un enorme acueducto de piedra que sigue en pie después de casi 2000 años.", "body": "Los romanos no solo conquistaron territorios: construyeron <b>obras tan sólidas</b> que muchas siguen de pie en España. Esta semana investigarás uno de esos monumentos y descubrirás sus secretos."}, {"type": "theory", "kicker": "La romanización", "h": "Infraestructuras que cambiaron Hispania", "body": "La <b>romanización</b> fue el proceso por el cual Roma extendió su cultura, su lengua y su forma de organizarse por toda Hispania. Una de sus huellas más visibles son las <b>infraestructuras</b>: acueductos como el de Segovia, teatros como el de Mérida, puentes como el de Alcántara y una extensa red de <b>calzadas</b> que unía todo el imperio.", "diagram": "<b>ACUEDUCTOS</b>: llevaban agua <br><b>TEATROS</b>: ocio y cultura <br><b>PUENTES</b>: cruzar ríos <br><b>CALZADAS</b>: unir ciudades"}, {"type": "quiz", "kicker": "Monumentos romanos", "h": "¿Para qué servían las calzadas romanas?", "q": "¿Cuál era la función principal de las calzadas romanas?", "opts": [{"t": "Unir y comunicar las ciudades del imperio", "ok": true}, {"t": "Servir de teatro para representaciones", "ok": false}, {"t": "Almacenar agua para las ciudades", "ok": false}, {"t": "Ser templos dedicados a los dioses", "ok": false}], "okMsg": "¡Exacto! Las calzadas conectaban Hispania con el resto del imperio romano.", "noMsg": "No es correcto. Las calzadas eran caminos empedrados que unían las ciudades entre sí."}, {"type": "reflect", "kicker": "Detective de monumentos", "h": "Investiga un monumento romano español", "body": "Elige un monumento romano que exista hoy en España y conviértete en su investigador.", "prompt": "Busca información sobre un monumento romano de España (por ejemplo, el Acueducto de Segovia, el Teatro de Mérida o el Puente de Alcántara). Anota <b>5 datos</b> sobre él (nombre, ciudad, para qué servía, cuándo se construyó y un dato curioso) y señala su localización en un mapa de España."}]},
  "p4:Oct:3": {"title": "El latín que todavía hablamos", "steps": [{"type": "hook", "kicker": "Hablando latín sin saberlo", "h": "¿Y si te dijera que hoy ya has hablado en latín?", "scenario": "Un niño dice la palabra 'familia' y su profesor le explica que esa misma palabra ya la usaban los romanos hace dos mil años.", "body": "Cuando hablas español, en realidad estás usando una lengua que nació del <b>latín</b>, el idioma de los romanos. Esta semana vas a descubrir cuánto de Roma sigue vivo en tu forma de hablar cada día."}, {"type": "theory", "kicker": "Una herencia con palabras", "h": "El latín, madre del castellano", "body": "La romanización no solo dejó edificios: también trajo la <b>lengua latina</b>, de la que nació el castellano, y el <b>derecho romano</b>, base de muchas leyes actuales. Muchísimas palabras que usamos hoy, como 'agua', 'casa' o 'padre', vienen directamente del latín que hablaban los romanos en Hispania.", "diagram": "<b>LENGUA</b>: latín → castellano <br><b>DERECHO</b>: leyes romanas → leyes actuales <br><b>EJEMPLOS</b>: aqua→agua, pater→padre"}, {"type": "quiz", "kicker": "Raíces latinas", "h": "¿De qué lengua viene el castellano?", "q": "¿Qué lengua dio origen al castellano que hablamos hoy?", "opts": [{"t": "El latín", "ok": true}, {"t": "El griego", "ok": false}, {"t": "El fenicio", "ok": false}, {"t": "El celta", "ok": false}], "okMsg": "¡Correcto! El castellano nació del latín que trajeron los romanos.", "noMsg": "No es correcto. Fue el latín, la lengua de los romanos, el origen del castellano."}, {"type": "reflect", "kicker": "Cazador de palabras", "h": "Encuentra la huella latina en tu vocabulario", "body": "Vas a buscar palabras de uso diario que provienen directamente del latín.", "prompt": "Busca y escribe <b>10 palabras castellanas</b> que tengan raíz latina (puedes usar un diccionario o preguntar a un adulto). Junto a cada palabra, escribe si conoces la palabra latina de la que proviene."}]},
  "p4:Oct:4": {"title": "Roma, el escenario de Dios", "steps": [{"type": "hook", "kicker": "El plan perfecto", "h": "¿Y si Roma formaba parte de un plan mucho más grande?", "scenario": "Un mensajero puede viajar por las calzadas romanas de un extremo a otro del imperio hablando una sola lengua y sintiéndose seguro.", "body": "Roma unió pueblos, caminos y lenguas como nunca antes se había visto. La Biblia nos enseña que ese momento de la historia no fue casualidad: fue <b>el tiempo perfecto de Dios</b>."}, {"type": "theory", "kicker": "En el cumplimiento del tiempo", "h": "Gálatas 4:4", "body": "La Biblia dice: <i>'Cuando vino el cumplimiento del tiempo, Dios envió a su Hijo'</i> (Gálatas 4:4). Las calzadas romanas, la lengua común y la paz del imperio (la llamada Pax Romana) ayudaron después a que el mensaje de Jesús se extendiera rápidamente por todo el mundo conocido. Roma, sin saberlo, preparó el camino para que llegara el mensaje de Dios.", "diagram": "<b>CALZADAS</b>: caminos para viajar <br><b>LENGUA COMÚN</b>: para comunicarse <br><b>PAZ ROMANA</b>: seguridad para viajar <br><b>RESULTADO</b>: el mensaje de Dios se extiende"}, {"type": "quiz", "kicker": "El versículo de la semana", "h": "¿Qué significa 'el cumplimiento del tiempo'?", "q": "Según Gálatas 4:4, ¿qué ocurrió 'cuando vino el cumplimiento del tiempo'?", "opts": [{"t": "Dios envió a su Hijo", "ok": true}, {"t": "Roma conquistó toda Europa", "ok": false}, {"t": "Se construyó el Coliseo", "ok": false}, {"t": "Terminó el Imperio Romano", "ok": false}], "okMsg": "¡Muy bien! Dios eligió el momento exacto de la historia para enviar a Jesús.", "noMsg": "No es correcto. El versículo dice que en ese momento exacto, Dios envió a su Hijo."}, {"type": "reflect", "kicker": "Roma, escenario de Dios", "h": "Crea tu infografía 'Hispania Romana'", "body": "Vas a resumir todo lo aprendido este mes uniendo la historia de Roma con el plan de Dios.", "prompt": "Elabora una infografía titulada <b>'Hispania Romana'</b> con dibujos y palabras clave sobre los pueblos prerromanos, las infraestructuras romanas y la herencia del latín. Añade el versículo de Gálatas 4:4 y escribe 2-3 frases explicando por qué crees que Roma fue, sin saberlo, 'el escenario de Dios'."}]},
  "p4:Nov:1": {"title": "El relieve de España", "steps": [{"type": "hook", "kicker": "Un país de contrastes", "h": "¿Sabías que España tiene una enorme meseta en el centro rodeada de montañas?", "scenario": "Una familia viaja en coche desde la costa hacia el centro de España y nota que el paisaje va subiendo poco a poco hasta llegar a una gran llanura elevada.", "body": "España tiene un relieve muy variado: llanuras elevadas, altas cordilleras y costas planas. Esta semana descubrirás la forma del terreno que pisas cada día."}, {"type": "theory", "kicker": "Las formas del terreno", "h": "Meseta, cordilleras y llanuras costeras", "body": "En el centro de España se extiende la <b>Meseta Central</b>, una gran llanura elevada. Alrededor de ella y por los bordes de la península se levantan cinco grandes <b>sistemas montañosos</b>: los Pirineos, la Cordillera Cantábrica, el Sistema Central, el Sistema Ibérico y el Sistema Bético. Junto al mar aparecen las <b>llanuras costeras</b>, terrenos más bajos y llanos.", "diagram": "<b>MESETA CENTRAL</b>: centro, elevada <br><b>5 SISTEMAS MONTAÑOSOS</b>: Pirineos, Cantábrica, Central, Ibérico, Bético <br><b>LLANURAS COSTERAS</b>: junto al mar"}, {"type": "quiz", "kicker": "Comprueba el relieve", "h": "¿Cómo se llama la gran llanura elevada del centro de España?", "q": "¿Qué nombre recibe la gran llanura elevada situada en el centro de la península?", "opts": [{"t": "La Meseta Central", "ok": true}, {"t": "El Sistema Ibérico", "ok": false}, {"t": "La Cordillera Cantábrica", "ok": false}, {"t": "Los Pirineos", "ok": false}], "okMsg": "¡Correcto! La Meseta Central ocupa gran parte del interior de España.", "noMsg": "No es correcto. Esa gran llanura elevada del centro se llama Meseta Central."}, {"type": "reflect", "kicker": "Colorea el relieve", "h": "Dibuja el mapa físico de España", "body": "Vas a representar las principales formas del relieve español en un mapa.", "prompt": "Dibuja o calca un mapa de España. Colorea la <b>Meseta Central</b> de un color, marca los <b>5 sistemas montañosos</b> (Pirineos, Cantábrica, Central, Ibérico y Bético) con otro color, y señala las <b>llanuras costeras</b> junto al mar con un tercer color. Escribe el nombre de cada elemento."}]},
  "p4:Nov:2": {"title": "Los grandes ríos de España", "steps": [{"type": "hook", "kicker": "Caminos de agua", "h": "¿Cuál es el río más largo que pasa cerca de tu ciudad?", "scenario": "Un niño ve en un mapa que un mismo río nace en las montañas, atraviesa varias ciudades y termina desembocando en el mar, muy lejos de donde nació.", "body": "Los ríos son como <b>caminos de agua</b> que recorren toda España, uniendo montañas, ciudades y costas. Esta semana vas a conocer a los cinco grandes protagonistas de nuestros ríos."}, {"type": "theory", "kicker": "Los 5 grandes ríos", "h": "Recorrido, afluentes y desembocadura", "body": "España tiene cinco grandes ríos: el <b>Tajo</b>, el <b>Ebro</b>, el <b>Duero</b>, el <b>Guadalquivir</b> y el <b>Guadiana</b>. Cada uno nace en unas montañas, recorre un camino distinto, recibe agua de otros ríos más pequeños llamados <b>afluentes</b>, y finalmente llega al mar por su <b>desembocadura</b>.", "diagram": "<b>TAJO</b>, <b>EBRO</b>, <b>DUERO</b>, <b>GUADALQUIVIR</b>, <b>GUADIANA</b> <br>NACIMIENTO → AFLUENTES → DESEMBOCADURA"}, {"type": "quiz", "kicker": "Ríos de España", "h": "¿Qué es un afluente?", "q": "¿Qué es un afluente de un río?", "opts": [{"t": "Un río más pequeño que aporta agua al río principal", "ok": true}, {"t": "El lugar donde el río llega al mar", "ok": false}, {"t": "Una montaña donde nace el río", "ok": false}, {"t": "Un embalse construido por personas", "ok": false}], "okMsg": "¡Correcto! Los afluentes son ríos más pequeños que se unen al río principal.", "noMsg": "No es correcto. Un afluente es un río más pequeño que entrega su agua a un río mayor."}, {"type": "reflect", "kicker": "Ficha de los 5 ríos", "h": "Investiga el recorrido de los grandes ríos", "body": "Vas a organizar la información esencial de los cinco grandes ríos de España.", "prompt": "Elabora una ficha o tabla con los <b>5 ríos</b> de España (Tajo, Ebro, Duero, Guadalquivir y Guadiana). Para cada uno anota: dónde nace, un <b>afluente principal</b> y dónde desemboca."}]},
  "p4:Nov:3": {"title": "El agua guardada: los embalses", "steps": [{"type": "hook", "kicker": "Agua para todos", "h": "¿De dónde viene el agua que sale del grifo de tu casa?", "scenario": "En verano, una familia visita un gran lago artificial rodeado de montañas y descubre que de ahí viene el agua que usan en su pueblo.", "body": "Muchas veces esa 'agua guardada' viene de un <b>embalse</b>, una gran construcción que retiene el agua de los ríos para que las personas puedan usarla durante todo el año."}, {"type": "theory", "kicker": "Uso humano del agua", "h": "¿Para qué sirven los embalses?", "body": "Los <b>embalses</b> son grandes depósitos de agua creados construyendo una presa en un río. Sirven para <b>abastecer de agua</b> a los pueblos y ciudades, para <b>regar los campos</b> de cultivo y para producir <b>energía eléctrica</b>. Gracias a ellos, el agua de los ríos se puede aprovechar incluso en las épocas más secas del año.", "diagram": "<b>EMBALSE</b> = presa + agua retenida <br>USOS: <b>agua potable</b>, <b>riego</b>, <b>energía eléctrica</b>"}, {"type": "quiz", "kicker": "Usos del agua", "h": "¿Para qué sirve un embalse?", "q": "¿Cuál de estas es una función de un embalse?", "opts": [{"t": "Abastecer de agua a pueblos y regar campos", "ok": true}, {"t": "Ser el nacimiento de todos los ríos", "ok": false}, {"t": "Construir calzadas romanas", "ok": false}, {"t": "Separar la meseta de las montañas", "ok": false}], "okMsg": "¡Correcto! Los embalses guardan agua para el consumo humano y el riego, entre otros usos.", "noMsg": "No es correcto. Un embalse guarda agua para abastecer poblaciones, regar campos y generar energía."}, {"type": "reflect", "kicker": "El embalse de mi tierra", "h": "Investiga el embalse más importante de tu comunidad", "body": "Vas a investigar un embalse cercano a donde vives y su importancia.", "prompt": "Busca información sobre el <b>embalse más importante de tu comunidad autónoma</b>. Anota su nombre, el <b>río</b> del que recoge el agua y el <b>uso principal</b> que se le da (agua potable, riego, energía...)."}]},
  "p4:Nov:4": {"title": "El agua como providencia", "steps": [{"type": "hook", "kicker": "Un regalo que no falta", "h": "¿Te has parado a pensar de dónde viene toda el agua que necesitamos?", "scenario": "Después de una larga sequía, llega la lluvia y los campos, antes secos, se llenan poco a poco de vida y color verde.", "body": "El relieve, los ríos y la lluvia no son casualidad: la Biblia nos enseña que Dios cuida de la tierra regándola con su providencia, es decir, con su cuidado constante."}, {"type": "theory", "kicker": "Visitas la tierra y la riegas", "h": "Salmo 65:9", "body": "El Salmo 65:9 dice: <i>'Visitas la tierra y la riegas; en gran manera la enriqueces'</i>. Las montañas recogen las nubes y la lluvia, los ríos reparten esa agua por toda España, y los embalses la guardan para que no falte. Todo ese sistema —relieve, ríos y embalses— es una muestra del <b>cuidado de Dios</b> sobre la creación.", "diagram": "<b>MONTAÑAS</b>: recogen la lluvia <br><b>RÍOS</b>: reparten el agua <br><b>EMBALSES</b>: la guardan <br>TODO: <b>providencia de Dios</b>"}, {"type": "quiz", "kicker": "El versículo de la semana", "h": "¿Qué nos enseña el Salmo 65:9?", "q": "Según el Salmo 65:9, ¿qué hace Dios con la tierra?", "opts": [{"t": "La visita y la riega, enriqueciéndola", "ok": true}, {"t": "La deja seca todo el año", "ok": false}, {"t": "La reparte entre los pueblos celtas", "ok": false}, {"t": "La convierte en una gran meseta", "ok": false}], "okMsg": "¡Muy bien! El Salmo nos recuerda que Dios cuida y riega la tierra con generosidad.", "noMsg": "No es correcto. El versículo dice que Dios visita la tierra, la riega y la enriquece en gran manera."}, {"type": "reflect", "kicker": "El agua como providencia", "h": "Crea tu mapa físico y ficha del embalse local", "body": "Vas a reunir todo lo aprendido este mes en un solo trabajo final.", "prompt": "Elabora un <b>mapa físico de España</b> señalando la Meseta, los 5 sistemas montañosos y los 5 grandes ríos. Añade una <b>ficha del embalse de tu comunidad</b> (nombre, río y uso) y escribe 2-3 frases explicando, con tus propias palabras, cómo el agua de España es una muestra de que Dios 'visita la tierra y la riega' (Salmo 65:9)."}]},
  "p4:Dic:1": {"title": "Detectives del Pasado", "steps": [{"type": "hook", "kicker": "Lengua Castellana · Diciembre", "h": "¿Puedes ser detective de la Historia?", "scenario": "Imagina que tienes un texto muy antiguo entre las manos y debes encontrar las pistas más importantes escondidas en sus palabras.", "body": "Los <b>textos históricos</b> cuentan hechos reales del pasado, pero usan palabras que no siempre conocemos. Esta semana aprenderás a leerlos como un auténtico investigador: buscando pistas y separando lo importante de lo secundario."}, {"type": "theory", "kicker": "Teoría", "h": "El vocabulario de la Historia", "body": "Los textos históricos usan palabras específicas como <b>reino</b>, <b>monarca</b>, <b>invasión</b> o <b>tratado</b>. Para entenderlos bien, primero debes <b>subrayar</b> las ideas principales: los hechos, personajes y fechas más importantes. No subrayes todo, solo lo esencial.", "diagram": "<b>Texto histórico</b><br>→ Vocabulario específico<br>→ Subrayado de ideas clave<br>→ Comprensión del pasado"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "La técnica correcta", "q": "¿Qué debes hacer al subrayar un texto histórico?", "opts": [{"t": "Marcar solo las ideas principales, no todo el texto", "ok": true}, {"t": "Subrayar cada palabra del texto", "ok": false}, {"t": "Subrayar solo los nombres propios", "ok": false}, {"t": "No subrayar nada y memorizarlo todo", "ok": false}], "okMsg": "¡Exacto! El buen lector separa lo importante de lo secundario.", "noMsg": "Recuerda: subrayar todo el texto no ayuda a distinguir lo esencial. Inténtalo de nuevo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Manos a la obra", "body": "Lee con atención el texto histórico adaptado que te ha entregado tu profesor.", "prompt": "Lee el texto histórico y <b>subraya</b> las 4 o 5 ideas principales. Guarda esta hoja en tu carpeta <i>'Leo historia en castellano'</i>: será el primer paso de tu entregable del mes."}]},
  "p4:Dic:2": {"title": "El Esquema: Ordena tus Ideas", "steps": [{"type": "hook", "kicker": "Lengua Castellana · Diciembre", "h": "¿Cómo cabe toda una época en un solo folio?", "scenario": "Un historiador ha leído cien páginas sobre un reino antiguo, pero solo dispone de un folio para explicarlo a sus alumnos.", "body": "La solución es el <b>esquema</b>: una forma de ordenar las ideas principales y secundarias para que toda la información quede clara de un solo vistazo."}, {"type": "theory", "kicker": "Teoría", "h": "Ideas principales y secundarias", "body": "Un buen esquema histórico organiza el texto en <b>3 ideas principales</b>, y cada una se apoya en <b>2 ideas secundarias</b> que la explican o completan. Así, la información queda ordenada como una escalera: de lo más importante a los detalles.", "diagram": "Idea principal 1<br>— secundaria 1a<br>— secundaria 1b<br><br>Idea principal 2<br>— secundaria 2a<br>— secundaria 2b<br><br>Idea principal 3<br>— secundaria 3a<br>— secundaria 3b"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Cuántas ideas secundarias?", "q": "En el esquema de esta semana, ¿cuántas ideas secundarias debe tener cada idea principal?", "opts": [{"t": "2", "ok": true}, {"t": "5", "ok": false}, {"t": "0", "ok": false}, {"t": "10", "ok": false}], "okMsg": "¡Correcto! Cada idea principal se apoya en 2 secundarias.", "noMsg": "Repasa el esquema: cada idea principal lleva exactamente 2 ideas secundarias."}, {"type": "reflect", "kicker": "Tu turno", "h": "Construye tu esquema", "body": "Ahora vas a organizar el texto de la semana pasada en forma de esquema.", "prompt": "Elabora un esquema con <b>3 ideas principales</b> del texto y <b>2 ideas secundarias</b> para cada una. Escríbelo con letra clara y añádelo a tu carpeta <i>'Leo historia en castellano'</i>."}]},
  "p4:Dic:3": {"title": "El Resumen: Cuéntalo con tus Palabras", "steps": [{"type": "hook", "kicker": "Lengua Castellana · Diciembre", "h": "¿Podrías contarle la Historia a tu abuela en un minuto?", "scenario": "Tu abuela te pregunta de qué trataba ese texto histórico tan largo que has estado estudiando, y solo tienes un minuto para contárselo.", "body": "Ahí es donde entra el <b>resumen</b>: contar lo esencial de un texto usando tus propias palabras, sin copiar frases enteras."}, {"type": "theory", "kicker": "Teoría", "h": "Cómo resumir bien", "body": "Un buen resumen histórico se apoya en el esquema que ya hiciste: recoge las ideas principales y algunas secundarias importantes, pero las cuenta con <b>tus propias palabras</b>, usando <b>conectores</b> como 'primero', 'después', 'a causa de' o 'como consecuencia'.", "diagram": "Esquema<br>↓<br>Resumen (8-10 oraciones)<br>↓<br>Conectores causales y temporales: porque, después, entonces, por eso"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Conectores en acción", "q": "¿Qué tipo de palabra es 'porque' dentro de un texto histórico?", "opts": [{"t": "Un conector causal, que explica el motivo de algo", "ok": true}, {"t": "Un nombre propio", "ok": false}, {"t": "Un adjetivo", "ok": false}, {"t": "Un signo de puntuación", "ok": false}], "okMsg": "¡Muy bien! 'Porque' conecta una causa con su consecuencia.", "noMsg": "Piensa en qué función cumple 'porque' dentro de una frase histórica. Vuelve a intentarlo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe tu resumen", "body": "Utiliza el esquema que ya preparaste para redactar el resumen final del texto.", "prompt": "Escribe un resumen del texto histórico en <b>8 a 10 oraciones</b>, con tus propias palabras y usando al menos dos conectores causales o temporales (por ejemplo 'porque', 'después'). Añádelo a tu carpeta <i>'Leo historia en castellano'</i>."}]},
  "p4:Dic:4": {"title": "Sabiduría: el Tesoro Más Grande", "steps": [{"type": "hook", "kicker": "Lengua Castellana · Diciembre", "h": "¿Cuál es el tesoro más valioso que puedes tener?", "scenario": "Durante todo el mes has aprendido a leer, subrayar, esquematizar y resumir textos históricos: has entrenado tu mente para buscar lo importante.", "body": "La Biblia también nos anima a buscar algo muy importante: la <b>sabiduría</b>. Esta semana descubrirás por qué adquirirla es como hallar el mejor de los tesoros."}, {"type": "theory", "kicker": "Teoría", "h": "Proverbios 4:7", "body": "El libro de Proverbios dice: <i>'Adquiere sabiduría y sobre todas tus posesiones adquiere inteligencia.'</i> (Proverbios 4:7). Así como subrayaste, esquematizaste y resumiste para entender mejor la Historia, Dios nos invita a buscar la <b>sabiduría</b> por encima de cualquier otra cosa que podamos poseer.", "diagram": "Leer con atención<br>→ Subrayar lo importante<br>→ Buscar sabiduría (Prov 4:7)<br>→ Entender mejor el mundo y a Dios"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "El versículo de la semana", "q": "Según Proverbios 4:7, ¿qué debemos adquirir sobre todas nuestras posesiones?", "opts": [{"t": "Inteligencia y sabiduría", "ok": true}, {"t": "Dinero y riquezas", "ok": false}, {"t": "Juguetes y ropa", "ok": false}, {"t": "Fama y popularidad", "ok": false}], "okMsg": "¡Así es! La sabiduría vale más que cualquier posesión.", "noMsg": "Vuelve a leer el versículo de Proverbios 4:7 con atención e inténtalo de nuevo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cierra tu carpeta del mes", "body": "Piensa en todo lo que has aprendido este mes sobre los textos históricos y sobre la sabiduría.", "prompt": "Escribe en tu cuaderno 3 frases explicando qué significa para ti 'adquirir sabiduría' según Proverbios 4:7, y cómo lo aprendido este mes (leer, subrayar, resumir) te ayuda a ser más sabio. Termina de completar tu carpeta <i>'Leo historia en castellano'</i>."}]},
  "p4:Feb:1": {"title": "Los Reinos de la Península", "steps": [{"type": "hook", "kicker": "Historia · Febrero", "h": "¿Sabías que España no siempre fue un solo país?", "scenario": "Viajamos en el tiempo hasta el siglo XII: la Península Ibérica está dividida en varios reinos, cada uno con su rey, su ejército y sus fronteras.", "body": "Esta semana descubrirás los <b>reinos medievales</b> que existían hace casi mil años: Castilla, Aragón, Navarra y Portugal."}, {"type": "theory", "kicker": "Teoría", "h": "Cuatro reinos, una península", "body": "En el siglo XII, la Península Ibérica estaba repartida en varios reinos cristianos: <b>Castilla</b>, <b>Aragón</b>, <b>Navarra</b> y <b>Portugal</b>. Cada uno tenía su propia capital, sus propias leyes y un rey que gobernaba sobre sus tierras y fronteras.", "diagram": "Reinos medievales (s. XII)<br>Castilla — capital y territorio propio<br>Aragón — capital y territorio propio<br>Navarra — capital y territorio propio<br>Portugal — capital y territorio propio"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Reinos medievales", "q": "¿Cuál de estos territorios NO era uno de los cuatro reinos medievales de esta semana (Castilla, Aragón, Navarra y Portugal)?", "opts": [{"t": "Al-Ándalus, territorio musulmán", "ok": true}, {"t": "Castilla", "ok": false}, {"t": "Aragón", "ok": false}, {"t": "Navarra", "ok": false}], "okMsg": "¡Correcto! Al-Ándalus era un territorio musulmán, distinto de los cuatro reinos cristianos.", "noMsg": "Repasa los cuatro reinos cristianos de la semana: Castilla, Aragón, Navarra y Portugal."}, {"type": "reflect", "kicker": "Tu turno", "h": "Dibuja el mapa", "body": "Vas a preparar el mapa de los reinos medievales que se verá en clase.", "prompt": "Dibuja un mapa de la Península Ibérica en el siglo XII y sitúa los <b>4 reinos medievales</b>: Castilla, Aragón, Navarra y Portugal. Escribe el nombre de la <b>capital</b> de cada reino y traza sus fronteras aproximadas."}]},
  "p4:Feb:2": {"title": "El Camino de Santiago", "steps": [{"type": "hook", "kicker": "Historia · Febrero", "h": "¿Te imaginas caminar cientos de kilómetros por fe?", "scenario": "Durante la Edad Media, miles de personas de toda Europa emprendían un largo viaje a pie o a caballo hacia una ciudad de Galicia.", "body": "Ese viaje se llama <b>Camino de Santiago</b>, y esta semana vas a descubrir sus rutas más importantes."}, {"type": "theory", "kicker": "Teoría", "h": "Dos grandes rutas", "body": "El Camino de Santiago tiene varias rutas históricas. La <b>Ruta Francesa</b> entra por los Pirineos y atraviesa el norte de España hasta Santiago de Compostela. La <b>Vía de la Plata</b> viene desde el sur, uniendo Sevilla con Galicia. Ambas terminan en el mismo destino: la tumba del apóstol Santiago.", "diagram": "Ruta Francesa: Pirineos → norte de España → Santiago<br>Vía de la Plata: Sevilla → oeste de España → Santiago<br>Destino común: Santiago de Compostela"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Las rutas del Camino", "q": "¿Desde qué ciudad del sur parte la Vía de la Plata hacia Santiago?", "opts": [{"t": "Sevilla", "ok": true}, {"t": "Barcelona", "ok": false}, {"t": "Pamplona", "ok": false}, {"t": "Zaragoza", "ok": false}], "okMsg": "¡Exacto! La Vía de la Plata parte de Sevilla hacia el norte.", "noMsg": "Repasa el mapa de la Vía de la Plata: su punto de partida está en el sur de España."}, {"type": "reflect", "kicker": "Tu turno", "h": "Traza las rutas", "body": "Ahora tú vas a trazar el recorrido de las dos rutas sobre un mapa.", "prompt": "En un mapa de España, traza con un color la <b>Ruta Francesa</b> (desde los Pirineos hasta Santiago) y con otro color la <b>Vía de la Plata</b> (desde Sevilla hasta Santiago). Señala el destino final: Santiago de Compostela."}]},
  "p4:Feb:3": {"title": "En la Piel de un Peregrino", "steps": [{"type": "hook", "kicker": "Historia · Febrero", "h": "¿Te atreverías a caminar semanas enteras sin mapa ni GPS?", "scenario": "Un peregrino medieval se despide de su familia sabiendo que tardará semanas, quizá meses, en llegar a Santiago... si es que llega.", "body": "Esta semana investigarás cómo era realmente la vida de un <b>peregrino medieval</b>: por qué viajaba, cuánto tardaba y qué peligros afrontaba."}, {"type": "theory", "kicker": "Teoría", "h": "Motivación, duración y peligros", "body": "Los peregrinos medievales viajaban por <b>motivos religiosos</b>: pedir perdón, cumplir una promesa o fortalecer su fe. El viaje podía durar <b>semanas o meses</b> a pie, y estaba lleno de <b>peligros</b> como el mal tiempo, los caminos difíciles, las enfermedades o los ladrones.", "diagram": "Peregrino medieval<br>Motivación → fe, perdón, promesa<br>Duración → semanas o meses<br>Peligros → caminos duros, enfermedades, ladrones"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "La vida del peregrino", "q": "¿Cuál de estas NO era una razón habitual para hacer el Camino de Santiago en la Edad Media?", "opts": [{"t": "Buscar un trabajo de vacaciones", "ok": true}, {"t": "Pedir perdón por los pecados", "ok": false}, {"t": "Cumplir una promesa religiosa", "ok": false}, {"t": "Fortalecer la fe", "ok": false}], "okMsg": "¡Correcto! Los peregrinos viajaban por motivos religiosos, no laborales.", "noMsg": "Piensa en qué buscaban realmente los peregrinos medievales: era algo relacionado con su fe."}, {"type": "reflect", "kicker": "Tu turno", "h": "Investiga al peregrino", "body": "Investiga un poco más sobre cómo era la vida de un peregrino medieval.", "prompt": "Investiga y escribe un pequeño informe explicando: 1) por qué motivo viajaba un peregrino medieval, 2) cuánto solía durar el viaje, y 3) qué peligros podía encontrar en el camino. Guarda este informe para tu trabajo <i>'Reinos medievales y Camino de Santiago'</i>."}]},
  "p4:Feb:4": {"title": "La Iglesia que Nunca Cae", "steps": [{"type": "hook", "kicker": "Historia · Febrero", "h": "¿Qué buscaban realmente los peregrinos al final del Camino?", "scenario": "Después de semanas de viaje, el peregrino medieval llega por fin a la catedral de Santiago de Compostela y entra en ella lleno de emoción.", "body": "Más allá de reinos, rutas y peligros, el Camino de Santiago tiene un motor común: la <b>fe</b> y la <b>Iglesia</b>. Esta semana descubrirás una promesa muy especial sobre la Iglesia."}, {"type": "theory", "kicker": "Teoría", "h": "Mateo 16:18", "body": "Jesús dijo a sus discípulos: <i>'Edificaré mi iglesia y las puertas del Hades no prevalecerán.'</i> (Mateo 16:18). Igual que las catedrales medievales, como la de Santiago, se construyeron para durar siglos, Jesús promete que su <b>Iglesia</b> es tan fuerte que nada podrá destruirla.", "diagram": "Reinos medievales y Camino de Santiago<br>→ La Iglesia como motor de fe<br>→ Mateo 16:18: 'Edificaré mi iglesia'<br>→ Promesa: nada podrá con ella"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "El versículo de la semana", "q": "Según Mateo 16:18, ¿qué no podrá vencer a la Iglesia que Jesús edifica?", "opts": [{"t": "Las puertas del Hades", "ok": true}, {"t": "Los reyes medievales", "ok": false}, {"t": "Las tormentas del Camino", "ok": false}, {"t": "Los ladrones del camino", "ok": false}], "okMsg": "¡Exacto! Ni las puertas del Hades prevalecerán contra la Iglesia.", "noMsg": "Vuelve a leer el versículo de Mateo 16:18 e inténtalo de nuevo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cierra tu trabajo del mes", "body": "Recuerda todo lo aprendido este mes: los reinos, el Camino de Santiago y la vida del peregrino.", "prompt": "Escribe 3 o 4 frases explicando qué relación encuentras entre el Camino de Santiago (un viaje de fe medieval) y la promesa de Mateo 16:18 de que la Iglesia de Jesús 'nunca caerá'. Con esto, completa tu trabajo <i>'Reinos medievales y Camino de Santiago'</i>."}]},
  "p4:Mar:1": {"title": "El Cid Campeador: un héroe desterrado", "steps": [{"type": "hook", "kicker": "Épica medieval", "h": "¿Qué harías si tu rey te desterrara injustamente?", "scenario": "Imagina que un día te dicen que debes abandonar tu ciudad para siempre, aunque no has hecho nada malo.", "body": "Eso le ocurrió al <b>Cid Campeador</b>, un caballero castellano del siglo XI. Su historia se cuenta en el poema más antiguo de la literatura española: el <b>Cantar del Mio Cid</b>."}, {"type": "theory", "kicker": "Un poema, un héroe", "h": "El Cantar del Mio Cid", "body": "El Cantar del Mio Cid es una <b>epopeya</b>, es decir, un largo poema que narra las hazañas de un héroe. Cuenta la historia de Rodrigo Díaz de Vivar, desterrado injustamente por el rey Alfonso VI, que recupera su honor con valentía, lealtad y <b>buen nombre</b>.", "diagram": "EL CID<br><b>Desterrado</b> injustamente<br>→ lucha con <b>valentía</b><br>→ actúa con <b>lealtad</b><br>→ recupera su <b>honor</b>"}, {"type": "quiz", "kicker": "Comprueba lo leído", "h": "¿Qué es el Cantar del Mio Cid?", "q": "¿Qué tipo de obra es el Cantar del Mio Cid?", "opts": [{"t": "Una epopeya que narra las hazañas de un héroe", "ok": true}, {"t": "Un libro de recetas medievales", "ok": false}, {"t": "Un diario personal del rey Alfonso VI", "ok": false}, {"t": "Una obra de teatro moderna", "ok": false}], "okMsg": "¡Correcto! Es una epopeya, el poema narrativo más antiguo conservado en castellano.", "noMsg": "No es eso. El Cantar del Mio Cid es una epopeya: narra en verso las hazañas de un héroe."}, {"type": "reflect", "kicker": "Tu turno", "h": "Los valores del Cid", "body": "Lee los fragmentos adaptados del Cantar del Mio Cid que te entregará tu profesor o guía familiar. Fíjate bien en cómo actúa el Cid ante las dificultades.", "prompt": "Escribe una lista con <b>5 valores</b> que veas en el Cid (por ejemplo: lealtad, valentía, paciencia...) y explica con una frase por qué cada uno se ve reflejado en el texto."}]},
  "p4:Mar:2": {"title": "Las palabras que cambian con el tiempo", "steps": [{"type": "hook", "kicker": "Lengua viva", "h": "¿Hablaban igual que nosotros hace 900 años?", "scenario": "Si leyeras el Cantar del Mio Cid tal y como se escribió, ¡seguro que no entenderías ni la mitad de las palabras!", "body": "El español ha cambiado mucho desde la Edad Media. Esta semana vamos a comparar el <b>castellano medieval</b> con el castellano que hablamos hoy."}, {"type": "theory", "kicker": "Del medievo a hoy", "h": "El castellano medieval vs el actual", "body": "Igual que las personas y las modas cambian, las lenguas también evolucionan con el tiempo. Muchas palabras del castellano medieval se transformaron poco a poco hasta convertirse en las que usamos hoy. Comparar ambas formas nos ayuda a entender mejor nuestra propia lengua.", "diagram": "CASTELLANO MEDIEVAL → CASTELLANO ACTUAL<br><b>fablar</b> → hablar<br><b>ome</b> → hombre<br><b>fazer</b> → hacer<br><b>mio Cid</b> → mi Cid<br><b>lidiar</b> → luchar"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Palabras medievales", "q": "¿Cómo se decía 'hablar' en castellano medieval?", "opts": [{"t": "Fablar", "ok": true}, {"t": "Charlar", "ok": false}, {"t": "Conversar", "ok": false}, {"t": "Decir", "ok": false}], "okMsg": "¡Exacto! 'Fablar' es el antepasado medieval de nuestro 'hablar'.", "noMsg": "No es correcto. En castellano medieval, 'hablar' se decía 'fablar'."}, {"type": "reflect", "kicker": "Investiga y compara", "h": "Tu tabla comparativa", "body": "Con ayuda de tu profesor o guía familiar, busca información sobre palabras del castellano medieval usadas en el Cantar del Mio Cid.", "prompt": "Elabora una <b>tabla comparativa</b> con 5 palabras del castellano medieval y su equivalente actual (por ejemplo: fablar/hablar). Puedes usar las que has aprendido hoy u otras nuevas que encuentres."}]},
  "p4:Mar:3": {"title": "Un elogio para el Cid", "steps": [{"type": "hook", "kicker": "Escritura creativa", "h": "¿Sabrías convencer a alguien de que el Cid fue un gran héroe?", "scenario": "Imagina que te piden escribir el discurso que se leería en un homenaje al Cid Campeador.", "body": "Ya conoces sus valores y sabes cómo hablaban en su época. Ahora es el momento de poner en práctica lo aprendido escribiendo un <b>elogio</b> al Cid, pero en castellano actual."}, {"type": "theory", "kicker": "Cómo se escribe un elogio", "h": "El elogio: alabar con palabras", "body": "Un <b>elogio</b> es un texto que alaba las cualidades y méritos de una persona. Para escribir uno bueno sobre el Cid, debes recordar sus <b>valores</b> (lealtad, valentía, honor...) y describir con tus propias palabras por qué merece ser recordado como un héroe.", "diagram": "ELOGIO AL CID<br>1. Quién fue<br>2. Sus valores<br>3. Sus hazañas<br>4. Por qué lo recordamos"}, {"type": "quiz", "kicker": "Antes de escribir", "h": "¿Qué es un elogio?", "q": "¿Qué es un elogio?", "opts": [{"t": "Un texto que alaba las cualidades de alguien", "ok": true}, {"t": "Una lista de la compra", "ok": false}, {"t": "Un texto que critica a una persona", "ok": false}, {"t": "Un poema sin sentido", "ok": false}], "okMsg": "¡Muy bien! Un elogio destaca y alaba los méritos de una persona.", "noMsg": "No es así. Un elogio es un texto que alaba las cualidades y méritos de alguien."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu elogio al Cid", "body": "Recuerda los 5 valores del Cid que identificaste en la semana 1 y las palabras medievales que aprendiste en la semana 2.", "prompt": "Escribe un <b>elogio al Cid en castellano actual</b> de entre 8 y 10 oraciones, explicando por qué merece ser recordado como un gran héroe castellano."}]},
  "p4:Mar:4": {"title": "El buen nombre del Cid", "steps": [{"type": "hook", "kicker": "Un tesoro que no se compra", "h": "¿Qué vale más: el dinero o el buen nombre?", "scenario": "El Cid perdió sus tierras y sus riquezas cuando fue desterrado, pero nunca dejó de defender su honor.", "body": "Esta última semana vamos a cerrar el portfolio del Cid descubriendo qué dice la Biblia sobre algo que él protegió por encima de todo: su <b>buen nombre</b>."}, {"type": "theory", "kicker": "Sabiduría bíblica", "h": "Proverbios 22:1", "body": "El libro de Proverbios nos enseña que hay cosas más valiosas que el dinero. Como el Cid, que prefirió recuperar su honor antes que acumular riquezas, la Biblia nos recuerda que el <b>buen nombre</b> —es decir, ser una persona honesta y de fiar— vale más que cualquier tesoro.", "diagram": "\"El buen nombre es preferible a las muchas riquezas.\" (Proverbios 22:1)<br>EL CID → defendió su <b>honor</b><br>LA BIBLIA → valora el <b>buen nombre</b>"}, {"type": "quiz", "kicker": "Comprueba el versículo", "h": "¿Qué dice Proverbios 22:1?", "q": "Según Proverbios 22:1, ¿qué es preferible a las muchas riquezas?", "opts": [{"t": "El buen nombre", "ok": true}, {"t": "Un caballo veloz", "ok": false}, {"t": "Una espada afilada", "ok": false}, {"t": "Un castillo grande", "ok": false}], "okMsg": "¡Correcto! El buen nombre —nuestra honestidad y reputación— vale más que cualquier riqueza.", "noMsg": "No es correcto. Proverbios 22:1 dice que el buen nombre es preferible a las muchas riquezas."}, {"type": "reflect", "kicker": "Cierra tu portfolio", "h": "El Cid y tu buen nombre", "body": "Piensa en cómo el Cid cuidó su honor incluso cuando lo perdió todo, y relaciona esto con lo que dice Proverbios 22:1.", "prompt": "Completa tu <b>Portfolio 'El Mio Cid'</b> escribiendo un texto breve donde expliques con tus palabras qué relación hay entre el honor del Cid y el versículo de Proverbios 22:1. Añade un compromiso personal: ¿cómo puedes tú cuidar tu 'buen nombre' cada día?"}]},
  "p4:Abr:1": {"title": "Dos reinos, una corona", "steps": [{"type": "hook", "kicker": "Un mapa que cambia", "h": "¿Cómo era España antes de ser un solo país?", "scenario": "Hace más de 500 años, la Península Ibérica estaba dividida en varios reinos distintos, cada uno con su propio rey.", "body": "Todo cambió cuando dos jóvenes herederos, <b>Fernando de Aragón</b> e <b>Isabel de Castilla</b>, se casaron y unieron sus reinos."}, {"type": "theory", "kicker": "La unión de dos coronas", "h": "La unión de Castilla y Aragón", "body": "Antes de 1469, Castilla y Aragón eran reinos independientes, cada uno con sus propias leyes y territorios. Cuando Isabel y Fernando se casaron, sus coronas se unieron bajo un mismo gobierno, sentando las bases de lo que más tarde sería <b>España</b>.", "diagram": "ANTES: Reino de Castilla + Reino de Aragón (separados)<br>↓ Boda de Isabel y Fernando<br>DESPUÉS: Corona unida"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "¿Quiénes unieron sus reinos?", "q": "¿Qué dos reinos se unieron gracias al matrimonio de Isabel y Fernando?", "opts": [{"t": "Castilla y Aragón", "ok": true}, {"t": "Portugal y Navarra", "ok": false}, {"t": "Granada y Sevilla", "ok": false}, {"t": "Cataluña y Valencia", "ok": false}], "okMsg": "¡Correcto! La boda de Isabel de Castilla y Fernando de Aragón unió ambas coronas.", "noMsg": "No es correcto. Fueron los reinos de Castilla y Aragón los que se unieron."}, {"type": "reflect", "kicker": "Dibuja la historia", "h": "Un mapa, dos épocas", "body": "Investiga con ayuda de tu profesor o guía familiar cómo estaba dividida la Península Ibérica antes de la unión de Fernando e Isabel, y cómo quedó después.", "prompt": "Dibuja un <b>mapa político</b> sencillo de la Península con dos versiones: 'antes' (reinos separados) y 'después' (la unión de Castilla y Aragón). Señala los nombres de los principales reinos en cada mapa."}]},
  "p4:Abr:2": {"title": "Isabel I de Castilla", "steps": [{"type": "hook", "kicker": "Una reina decidida", "h": "¿Cómo era la reina que cambió el destino de España?", "scenario": "Isabel I no solo se casó y unió reinos: tomó decisiones que marcarían el rumbo de toda una nación durante siglos.", "body": "Esta semana vamos a conocer más de cerca a esta reina castellana, su fe y algunas de sus decisiones más importantes."}, {"type": "theory", "kicker": "Retrato de una reina", "h": "Perfil de Isabel I de Castilla", "body": "Isabel I nació en Madrigal de las Altas Torres en 1451 y llegó a ser reina de Castilla. Fue una mujer de profunda <b>fe cristiana</b>, que tomó decisiones que cambiaron la historia: se casó con Fernando de Aragón, impulsó la conquista de Granada y apoyó el viaje de Cristóbal Colón hacia América.", "diagram": "ISABEL I DE CASTILLA<br>Nace en 1451<br>Fe cristiana profunda<br>3 decisiones clave:<br>1) Unión con Aragón<br>2) Toma de Granada<br>3) Apoyo al viaje de Colón"}, {"type": "quiz", "kicker": "Repasa el perfil", "h": "Datos sobre Isabel I", "q": "¿Cuál de estas fue una decisión importante de Isabel I?", "opts": [{"t": "Apoyar el viaje de Colón hacia América", "ok": true}, {"t": "Fundar la ciudad de Roma", "ok": false}, {"t": "Construir el Coliseo", "ok": false}, {"t": "Firmar la paz con Inglaterra en el siglo XX", "ok": false}], "okMsg": "¡Correcto! Isabel I apoyó el viaje de Cristóbal Colón, una de sus decisiones más importantes.", "noMsg": "No es correcto. Una de sus grandes decisiones fue apoyar el viaje de Colón hacia América."}, {"type": "reflect", "kicker": "Investiga y redacta", "h": "El perfil de Isabel I", "body": "Con ayuda de tu profesor o guía familiar, busca datos sobre Isabel I de Castilla.", "prompt": "Elabora un <b>perfil de Isabel I</b> que incluya: su fecha de nacimiento, una descripción breve de su fe cristiana y las <b>3 decisiones importantes</b> que tomó como reina."}]},
  "p4:Abr:3": {"title": "El diario de Colón", "steps": [{"type": "hook", "kicker": "Un viaje que cambió el mundo", "h": "¿Qué sintió Colón al ver tierra por primera vez?", "scenario": "Después de semanas navegando sin saber qué encontraría, un marinero grita: '¡Tierra!'", "body": "El 12 de octubre de 1492, Cristóbal Colón y su tripulación llegaron a un continente desconocido para los europeos de la época. Vamos a leer su propio relato de aquel día."}, {"type": "theory", "kicker": "Un testigo directo", "h": "El descubrimiento de América", "body": "Cristóbal Colón, apoyado por los Reyes Católicos, zarpó buscando una ruta hacia Asia y llegó, sin saberlo, a un nuevo continente: <b>América</b>. Su diario de viaje es una fuente histórica que nos permite conocer, con sus propias palabras, cómo vivió aquel momento tan importante.", "diagram": "12 DE OCTUBRE DE 1492<br>Colón llega a tierra<br>→ Nace el contacto entre Europa y América<br>→ Se abre una nueva etapa de la Historia"}, {"type": "quiz", "kicker": "Comprueba la fecha", "h": "El día del descubrimiento", "q": "¿En qué fecha llegó Colón a América?", "opts": [{"t": "12 de octubre de 1492", "ok": true}, {"t": "4 de julio de 1776", "ok": false}, {"t": "1 de enero de 1500", "ok": false}, {"t": "12 de octubre de 1592", "ok": false}], "okMsg": "¡Correcto! El 12 de octubre de 1492 Colón llegó a tierras americanas.", "noMsg": "No es correcto. La fecha exacta es el 12 de octubre de 1492."}, {"type": "reflect", "kicker": "Ponte en su lugar", "h": "El diario de Colón", "body": "Lee el fragmento adaptado del diario de Colón del 12 de octubre de 1492 que te entregará tu profesor o guía familiar.", "prompt": "Imagina que eres un marinero de la tripulación de Colón. Escribe unas líneas de tu propio 'diario' contando cómo te sentiste al escuchar la palabra '¡Tierra!' después de tantos días de viaje."}]},
  "p4:Abr:4": {"title": "La providencia en 1492", "steps": [{"type": "hook", "kicker": "Detrás de la historia", "h": "¿Quién decide realmente quién gobierna?", "scenario": "En 1492 ocurrieron tres grandes eventos que cambiaron España para siempre: la unión de los reinos, la toma de Granada y la llegada a América.", "body": "Esta última semana vamos a mirar estos hechos históricos con otros ojos: los de la Biblia, que nos habla de quién está detrás de los grandes cambios de la historia."}, {"type": "theory", "kicker": "Sabiduría bíblica", "h": "Daniel 2:21", "body": "El profeta Daniel escribió que es Dios quien <b>cambia los tiempos</b> y <b>pone y quita reyes</b>. Al mirar 1492 —la unión de Castilla y Aragón, el fin de la Reconquista y el descubrimiento de América— podemos reconocer la <b>providencia</b>: la idea de que Dios está presente y actúa en los grandes acontecimientos de la historia.", "diagram": "\"Él cambia los tiempos y las edades; quita reyes y pone reyes.\" (Daniel 2:21)<br>1492: unión de reinos + toma de Granada + llegada a América<br>→ LA PROVIDENCIA EN LA HISTORIA"}, {"type": "quiz", "kicker": "Comprueba el versículo", "h": "¿Qué dice Daniel 2:21?", "q": "Según Daniel 2:21, ¿qué hace Dios con los tiempos y los reyes?", "opts": [{"t": "Los cambia y los pone y los quita", "ok": true}, {"t": "No tiene ningún poder sobre ellos", "ok": false}, {"t": "Los ignora por completo", "ok": false}, {"t": "Los deja siempre igual para siempre", "ok": false}], "okMsg": "¡Correcto! Daniel 2:21 dice que Dios cambia los tiempos y las edades, y quita y pone reyes.", "noMsg": "No es correcto. Daniel 2:21 dice que Dios cambia los tiempos y las edades, y quita y pone reyes."}, {"type": "reflect", "kicker": "Cierra tu trabajo", "h": "Tres eventos, una providencia", "body": "Repasa lo que has aprendido sobre la unión de Castilla y Aragón, la toma de Granada y el descubrimiento de América, y relaciónalo con el versículo de Daniel 2:21.", "prompt": "Completa el trabajo <b>'1492: tres eventos que cambiaron España'</b> explicando brevemente cada uno de los tres eventos y añadiendo una reflexión final sobre cómo ves la providencia de Dios en estos hechos históricos."}]},
  "p4:May:1": {"title": "¿Dónde vive España? El mapa de la población", "steps": [{"type": "hook", "kicker": "Geografía en acción", "h": "Si repartieras a todos los españoles por el mapa, ¿se quedarían quietos... o se amontonarían en algunas zonas?", "scenario": "Imagina un tablero de juego con 47 millones de fichas. Al soltarlas sobre el mapa de España, casi todas caen cerca del mar o alrededor de una gran ciudad, mientras que el centro del tablero queda casi vacío.", "body": "Eso es exactamente lo que ocurre en la realidad. España tiene <b>zonas muy pobladas</b> y otras casi vacías. Esta semana vamos a descubrir por qué la gente elige vivir donde vive."}, {"type": "theory", "kicker": "Sabías que...", "h": "Interior vacío, costas llenas", "body": "La población española no se reparte de forma uniforme. La mayoría de la gente vive en las <b>zonas costeras</b> (Mediterráneo, Cantábrico, Atlántico) y en las grandes ciudades, mientras que gran parte del <b>interior</b> (Castilla, Extremadura, Aragón...) tiene muy poca densidad de población. A esto se le llama <b>densidad de población</b>: el número de personas que viven en cada kilómetro cuadrado. Tres causas principales explican este reparto: el <b>clima</b> más suave en la costa, las <b>oportunidades de trabajo</b> (turismo, industria, puertos) y la <b>cercanía al mar</b> para el comercio desde hace siglos.", "diagram": "<b>COSTA</b> → mucha gente, clima suave, trabajo, puertos <br> <b>INTERIOR</b> → poca gente, clima extremo, menos industria <br> <b>DENSIDAD DE POBLACIÓN</b> = personas ÷ km²"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Dónde vive la mayoría de la población española?", "q": "¿En qué zonas de España vive la mayor parte de la población?", "opts": [{"t": "En las zonas de costa y en las grandes ciudades", "ok": true}, {"t": "En el centro exacto de la Península, lejos de todo", "ok": false}, {"t": "Repartida exactamente igual en todo el territorio", "ok": false}, {"t": "Solo en las montañas más altas", "ok": false}], "okMsg": "¡Correcto! El clima, el trabajo y el mar atraen a la mayoría de la población hacia las costas y las grandes ciudades.", "noMsg": "Casi... Piensa en el clima y el trabajo: ¿dónde hay más oportunidades, en la costa o en el interior? Vuelve a intentarlo."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu propio mapa de población", "body": "Vas a convertirte en geógrafo por un día. Dibuja o busca un mapa de España y señala con puntos de colores dónde vive más gente y dónde vive menos.", "prompt": "Dibuja un mapa sencillo de España. Marca con puntos rojos las zonas MÁS pobladas (costas y grandes ciudades) y con puntos azules las zonas MENOS pobladas (interior). Después, escribe las <b>3 causas</b> que explican por qué la gente vive más en unos sitios que en otros."}]},
  "p4:May:2": {"title": "Mi ciudad ha cambiado: el proceso de urbanización", "steps": [{"type": "hook", "kicker": "Detective urbano", "h": "¿Sabrías reconocer tu ciudad o tu pueblo en una foto de hace 50 años?", "scenario": "Tus abuelos caminan contigo por el centro de tu localidad y de pronto dicen: 'Aquí antes había un campo' o 'esta calle no existía'. Te sorprende pensar que el lugar donde vives ha cambiado tanto en tan poco tiempo.", "body": "Las ciudades españolas han crecido muchísimo en las últimas décadas. A este fenómeno lo llamamos <b>urbanización</b>: el proceso por el cual cada vez más personas se trasladan a vivir en ciudades."}, {"type": "theory", "kicker": "Sabías que...", "h": "Del campo a la ciudad", "body": "Hace 60-70 años, muchos españoles vivían en pueblos y trabajaban en el campo. A partir de los años 60, millones de personas se trasladaron a las ciudades buscando <b>trabajo en fábricas y servicios</b>. Este movimiento se llama <b>éxodo rural</b>. Las ciudades crecieron muy rápido: se construyeron nuevos barrios, carreteras, colegios y hospitales. Hoy, más del 80% de los españoles vive en zonas urbanas. Investigar cómo ha crecido tu propia ciudad te ayuda a entender la <b>historia real</b> de tu entorno, no solo la de los libros.", "diagram": "AYER: pueblos + campo <br> AÑOS 60-70: <b>éxodo rural</b> (del campo a la ciudad) <br> HOY: <b>urbanización</b> → más del 80% vive en ciudades"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué es la urbanización?", "q": "¿Cómo se llama el proceso por el que cada vez más personas viven en ciudades?", "opts": [{"t": "Urbanización", "ok": true}, {"t": "Colonización", "ok": false}, {"t": "Globalización", "ok": false}, {"t": "Meteorología", "ok": false}], "okMsg": "¡Exacto! La urbanización es el crecimiento de las ciudades y el aumento de personas que viven en ellas.", "noMsg": "No es esa. Piensa en la palabra que se parece a 'urbano', que significa 'de ciudad'. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Investiga el pasado de tu ciudad", "body": "Convierte esta semana en una pequeña investigación familiar. Pregunta a un adulto mayor (abuelos, vecinos) cómo era tu localidad hace 50 años.", "prompt": "Pregunta a un familiar o vecino mayor: ¿cómo era tu ciudad o pueblo hace 50 años? ¿Ha crecido mucho? Escribe 3-4 frases explicando <b>cuánto ha cambiado</b> y <b>por qué</b> (trabajo, nuevas familias, servicios...). Si puedes, busca una foto antigua para comparar."}]},
  "p4:May:3": {"title": "Madrid, Barcelona y Sevilla: tres formas de ser ciudad", "steps": [{"type": "hook", "kicker": "De viaje sin salir de casa", "h": "¿Qué tienen en común Madrid, Barcelona y Sevilla... y qué las hace tan diferentes?", "scenario": "Imagina que puedes teletransportarte durante un día a cada una de estas tres ciudades. En una ves el Palacio Real, en otra el mar Mediterráneo y edificios modernistas, y en la tercera calles con aroma a azahar y un gran río.", "body": "Cada ciudad española tiene su propia <b>identidad</b>: su historia, su forma de crecer y lo que la hace única. Vamos a conocer tres grandes ciudades: <b>Madrid</b>, <b>Barcelona</b> y <b>Sevilla</b>."}, {"type": "theory", "kicker": "Sabías que...", "h": "Tres ciudades, tres identidades", "body": "<b>Madrid</b> es la capital de España, situada en el centro de la Península; creció mucho porque allí está el gobierno y muchas empresas. <b>Barcelona</b> está en la costa mediterránea, es un importante puerto y centro industrial, con una identidad propia muy fuerte. <b>Sevilla</b>, en el sur, junto al río Guadalquivir, es una ciudad con siglos de historia, puerto fluvial y gran importancia cultural. Las tres han crecido de forma distinta según su <b>situación geográfica</b> y su historia, pero comparten algo: son motores económicos y culturales de sus regiones.", "diagram": "<b>MADRID</b> → centro, capital, gobierno <br> <b>BARCELONA</b> → costa, puerto, industria <br> <b>SEVILLA</b> → sur, río Guadalquivir, historia"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Cuál es la capital de España?", "q": "¿Qué ciudad es la capital de España y está situada en el centro de la Península?", "opts": [{"t": "Madrid", "ok": true}, {"t": "Barcelona", "ok": false}, {"t": "Sevilla", "ok": false}, {"t": "Valencia", "ok": false}], "okMsg": "¡Correcto! Madrid es la capital, situada en el centro, y allí se encuentra el gobierno de España.", "noMsg": "No es esa. Recuerda: es la ciudad situada justo en el centro de la Península. ¡Inténtalo de nuevo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Crea el perfil de tres ciudades", "body": "Vas a elaborar tu propia ficha de geógrafo sobre Madrid, Barcelona y Sevilla (o las ciudades más próximas a ti si lo prefieres).", "prompt": "Haz una ficha para cada ciudad (Madrid, Barcelona y Sevilla) con estos datos: <b>ubicación</b> (centro, costa o sur), <b>un símbolo o monumento</b> famoso, y <b>una palabra</b> que resuma su identidad. Puedes añadir un dibujo pequeño para cada una."}]},
  "p4:May:4": {"title": "Buscad la paz de la ciudad", "steps": [{"type": "hook", "kicker": "Fe y ciudad", "h": "¿Puede una ciudad ser también un lugar de fe y de oración?", "scenario": "Piensa en tu ciudad o tu pueblo: sus calles, sus plazas, su gente. Ahora imagina que Dios te pide que cuides ese lugar, que trabajes por su bien y que ores por él, aunque no sea perfecto.", "body": "Después de conocer cómo se forman y crecen las ciudades, esta semana descubrimos que la Biblia también habla de las ciudades como <b>lugares que Dios ama y donde quiere que su pueblo sea una bendición</b>."}, {"type": "theory", "kicker": "Sabías que...", "h": "Jeremías y la ciudad de Babilonia", "body": "El profeta <b>Jeremías</b> escribió a un pueblo que vivía lejos de su tierra, en una ciudad extranjera llamada Babilonia. En vez de decirles que se quejaran o que solo pensaran en volver a casa, Dios les dio un mensaje sorprendente: <b>'Buscad la paz de la ciudad; rogad por ella al Señor'</b> (Jeremías 29:7). Esto significa que, estén donde estén, las personas de fe están llamadas a trabajar por el bien de su ciudad y a orar por ella, sea Madrid, Sevilla, un pequeño pueblo o cualquier lugar del mundo.", "diagram": "CIUDAD = lugar para vivir <br> + CIUDAD = lugar para <b>servir y orar</b> <br> Jeremías 29:7 → 'Buscad la paz de la ciudad; rogad por ella al Señor'"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué pedía Jeremías 29:7?", "q": "Según Jeremías 29:7, ¿qué debía hacer el pueblo por la ciudad donde vivía?", "opts": [{"t": "Buscar su paz y orar por ella", "ok": true}, {"t": "Abandonarla lo antes posible", "ok": false}, {"t": "Ignorarla por completo", "ok": false}, {"t": "Construir un muro para separarse de ella", "ok": false}], "okMsg": "¡Muy bien! Jeremías 29:7 nos enseña a buscar la paz de la ciudad y a orar por ella, sea cual sea el lugar donde vivamos.", "noMsg": "No es esa la respuesta. Recuerda el versículo: habla de 'buscar' algo bueno para la ciudad y de 'rogar', es decir, orar. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Las ciudades como espacios de fe", "body": "Es hora de reunir todo lo aprendido este mes sobre población, urbanización, ciudades españolas y fe.", "prompt": "Completa tu entregable final: en una misma hoja, pega o dibuja tu <b>mapa de población</b> (semana 1) y tu <b>perfil de las 3 ciudades</b> (semana 3). Añade al final una frase corta escrita por ti que sea una oración por tu ciudad, inspirada en Jeremías 29:7."}]},
  "p4:Jun:1": {"title": "La poesía de Antonio Machado", "steps": [{"type": "hook", "kicker": "Palabras con música", "h": "¿Puede un poema sonar como una canción sin tener música?", "scenario": "Lees en voz alta unos versos y, sin darte cuenta, empiezas a marcar un ritmo con el pie, como si escucharas una melodía escondida entre las palabras.", "body": "Esta semana entramos en el mundo de la <b>lírica</b>, uno de los tres grandes géneros literarios, de la mano de uno de los poetas españoles más queridos: <b>Antonio Machado</b>."}, {"type": "theory", "kicker": "Sabías que...", "h": "Narrativa, lírica y drama", "body": "La literatura se organiza en <b>tres grandes géneros</b>: la <b>narrativa</b> (cuentos, novelas, que cuentan historias), la <b>lírica</b> (poemas, que expresan sentimientos) y el <b>drama</b> (teatro, escrito para representarse). En los poemas es fundamental fijarse en la <b>rima</b> (sonidos que se repiten al final de los versos), el <b>ritmo</b> (la musicalidad al leerlos) y el <b>verso</b> (cada línea del poema). Antonio Machado escribió poemas sobre Castilla, el paso del tiempo y los caminos, con un lenguaje sencillo pero muy emotivo.", "diagram": "3 GÉNEROS: <b>NARRATIVA</b> (cuenta) · <b>LÍRICA</b> (siente) · <b>DRAMA</b> (representa) <br> En un poema: <b>VERSO</b> (línea) + <b>RIMA</b> (sonido final) + <b>RITMO</b> (musicalidad)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué género expresa sentimientos en verso?", "q": "¿Cómo se llama el género literario que expresa sentimientos a través de poemas?", "opts": [{"t": "Lírica", "ok": true}, {"t": "Narrativa", "ok": false}, {"t": "Drama", "ok": false}, {"t": "Ensayo", "ok": false}], "okMsg": "¡Correcto! La lírica es el género de los poemas, donde se expresan sentimientos y emociones.", "noMsg": "No es esa. Piensa en la palabra relacionada con 'lira', un instrumento musical antiguo. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Lee y analiza un poema de Machado", "body": "Busca (con ayuda de un adulto) un poema breve de Antonio Machado y léelo en voz alta, despacio, fijándote en su sonido.", "prompt": "Lee un poema de Antonio Machado. Escribe: 1) ¿de qué trata principalmente? (el <b>tema</b>), 2) busca dos palabras del final de los versos que rimen entre sí y escríbelas."}]},
  "p4:Jun:2": {"title": "Al teatro: primera lectura dramática", "steps": [{"type": "hook", "kicker": "¡Luces, telón... texto!", "h": "¿Cómo se lee un texto que está escrito para ser representado, no solo leído?", "scenario": "Abres un libro y, en vez de encontrar párrafos normales, ves nombres en mayúscula seguidos de dos puntos y frases entre paréntesis como '(entra corriendo)'. Al principio te desconcierta... hasta que entiendes que estás leyendo una obra de teatro.", "body": "Esta semana descubrimos el tercer gran género literario: el <b>drama</b> o teatro, a través de una primera lectura de <b>teatro clásico español</b> adaptado para tu edad."}, {"type": "theory", "kicker": "Sabías que...", "h": "El texto teatral tiene su propio lenguaje", "body": "A diferencia de un cuento, el texto de teatro está escrito para ser <b>representado</b> ante un público. Tiene características especiales: los <b>diálogos</b> (lo que dicen los personajes), precedidos por su nombre, y las <b>acotaciones</b> (instrucciones entre paréntesis o en cursiva que indican gestos, movimientos o el escenario). En una escena de teatro clásico español, cada personaje tiene su propia forma de hablar y sus propios motivos. Leer teatro exige fijarse bien en <b>quién habla</b> y <b>qué está ocurriendo</b> en cada momento, casi como si fuéramos detectives de la escena.", "diagram": "TEXTO TEATRAL = <b>DIÁLOGOS</b> (lo que dicen) + <b>ACOTACIONES</b> (lo que hacen/sienten) <br> Preguntas clave: ¿QUIÉN habla? ¿QUÉ sucede?"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué son las acotaciones?", "q": "En una obra de teatro, ¿qué son las acotaciones?", "opts": [{"t": "Instrucciones sobre gestos, movimientos o el escenario", "ok": true}, {"t": "El título de la obra", "ok": false}, {"t": "El nombre del autor", "ok": false}, {"t": "La rima de los versos", "ok": false}], "okMsg": "¡Exacto! Las acotaciones indican cómo se mueven o actúan los personajes y cómo es el escenario.", "noMsg": "No es esa. Las acotaciones suelen ir entre paréntesis y explican gestos o movimientos. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Lee una escena y analízala", "body": "Lee (o escucha leer) una escena breve de teatro clásico español adaptado para tu edad.", "prompt": "Después de leer la escena, responde por escrito: ¿<b>quién habla</b> en la escena (qué personajes)? y ¿<b>qué sucede</b> exactamente? Si te atreves, léela en voz alta con un familiar, cada uno un personaje."}]},
  "p4:Jun:3": {"title": "Mi propio poema: 8 versos para España", "steps": [{"type": "hook", "kicker": "Ahora te toca a ti", "h": "¿Y si el próximo poema sobre España lo escribieras tú?", "scenario": "Tienes delante una hoja en blanco y un lápiz. Piensas en un paisaje, un recuerdo o un sentimiento sobre tu tierra... y de pronto las palabras empiezan a ordenarse en tu cabeza como si tuvieran ritmo propio.", "body": "Después de leer poesía y teatro, esta semana das el salto de <b>lector</b> a <b>autor</b>: vas a escribir tu propio poema."}, {"type": "theory", "kicker": "Sabías que...", "h": "Cómo se construye un poema sencillo", "body": "Para escribir un poema no hace falta ser un genio: basta con elegir un <b>tema</b> que te emocione (España, tu región, un paisaje, una fiesta) y organizar tus ideas en <b>versos</b> (líneas cortas). Puedes buscar que algunos versos <b>rimen</b> entre sí, es decir, que terminen con sonidos parecidos, aunque también existen poemas sin rima. Lo más importante es cuidar el <b>ritmo</b>: leer en voz alta lo que escribes y comprobar si suena bien. Un poema de <b>8 versos</b> es como una pequeña canción hecha de palabras.", "diagram": "PASO 1: elige TEMA <br> PASO 2: escribe 8 VERSOS <br> PASO 3: busca RIMA y RITMO <br> PASO 4: ¡léelo en voz alta!"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué es un verso?", "q": "En un poema, ¿qué es un verso?", "opts": [{"t": "Cada línea del poema", "ok": true}, {"t": "El título del poema", "ok": false}, {"t": "El autor del poema", "ok": false}, {"t": "El final de una obra de teatro", "ok": false}], "okMsg": "¡Correcto! Cada línea de un poema se llama verso, y el conjunto de versos forma el poema.", "noMsg": "No es esa. Piensa en cada línea escrita del poema, una debajo de otra. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu poema", "body": "Ha llegado el momento de crear. No te preocupes por que sea perfecto: lo importante es expresar lo que sientes.", "prompt": "Escribe un poema de <b>8 versos</b> sobre España o tu región (puede ser sobre un paisaje, una costumbre, una fiesta o un recuerdo). Intenta que al menos dos versos rimen entre sí. Después, léelo en voz alta para comprobar su ritmo."}]},
  "p4:Jun:4": {"title": "Cantad al Señor un cántico nuevo", "steps": [{"type": "hook", "kicker": "La poesía más antigua de alabanza", "h": "¿Sabías que algunos de los poemas más antiguos que existen son cantos de alabanza a Dios?", "scenario": "Imagina un gran templo lleno de gente cantando juntos versos que hablan de gratitud y esperanza, con palabras cuidadosamente elegidas, como un poema hecho para ser cantado por todos.", "body": "Después de leer, analizar y escribir poesía, cerramos el mes descubriendo que la Biblia también contiene <b>poesía</b>: los <b>salmos</b>, cantos y oraciones escritos en verso."}, {"type": "theory", "kicker": "Sabías que...", "h": "Los salmos: poesía y alabanza", "body": "El libro de los <b>Salmos</b> es una colección de poemas y cantos que expresan alabanza, gratitud, tristeza o esperanza a Dios. El <b>Salmo 96:1</b> dice: <b>'Cantad al Señor un cántico nuevo; cantad, toda la tierra'</b>. Es una invitación a expresar con creatividad, como los poetas, algo tan grande como la fe. Igual que Antonio Machado usaba la poesía para hablar de Castilla y del tiempo, los salmistas usaban la poesía para hablar de su relación con Dios: con versos, ritmo e imágenes bellas.", "diagram": "POESÍA HUMANA → expresa sentimientos (Machado) <br> POESÍA BÍBLICA → <b>SALMOS</b>, expresan alabanza a Dios <br> Salmo 96:1 → 'Cantad al Señor un cántico nuevo'"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué son los Salmos?", "q": "¿Qué son los Salmos en la Biblia?", "opts": [{"t": "Poemas y cantos de alabanza y oración a Dios", "ok": true}, {"t": "Cartas escritas por un rey", "ok": false}, {"t": "Reglas de comportamiento", "ok": false}, {"t": "Un tipo de obra de teatro", "ok": false}], "okMsg": "¡Muy bien! Los Salmos son poemas y cantos que expresan alabanza, gratitud y oración a Dios.", "noMsg": "No es esa. Piensa en 'poesía' y 'canto de alabanza'. ¡Vuelve a intentarlo!"}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu cuaderno literario: géneros de la lengua", "body": "Es momento de reunir todo lo trabajado este mes: la lírica de Machado, el teatro clásico y tu propio poema.", "prompt": "Completa tu <b>cuaderno literario 'Géneros de la lengua'</b>: incluye tus notas sobre el poema de Machado, tu análisis de la escena de teatro y tu poema de 8 versos. Añade una última página con un pequeño verso propio, inspirado en el Salmo 96:1, que sea como un 'cántico nuevo' de gratitud."}]},
  "p4:Jul:1": {"title": "Un viaje en el tiempo: de Roma a España", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 1", "h": "¿Sabrías contar la historia de España... en una sola imagen?", "scenario": "Imagina que un amigo de otro país te pregunta: '¿Qué le ha pasado a España a lo largo de los siglos?' Solo tienes un folio y unos rotuladores para responder.", "body": "Este mes vas a crear tu <b>Proyecto Final</b>: un trabajo donde reunirás todo lo que has aprendido este curso sobre la <b>historia y la geografía de España</b>. Empezamos construyendo una línea de tiempo que vaya desde la <b>Hispania romana</b> hasta el <b>siglo XVI</b>, pasando por los reinos medievales, el Camino de Santiago y los Reyes Católicos."}, {"type": "theory", "kicker": "Cómo se construye una línea de tiempo", "h": "Organizar la historia paso a paso", "body": "Una línea de tiempo ordena los hechos según cuándo ocurrieron, del más antiguo al más reciente. Este curso hemos viajado por cuatro grandes etapas: la <b>Hispania romana</b> (con sus calzadas, acueductos y ciudades), los <b>reinos medievales</b> y el <b>Camino de Santiago</b>, la época del <b>Cantar del Mio Cid</b>, y por último los <b>Reyes Católicos</b> con el año clave de <b>1492</b>. Para tu línea de tiempo, coloca cada etapa en orden, añade una fecha aproximada, un dibujo y una frase que la explique.", "diagram": "<b>Hispania romana</b><br>↓<br><b>Reinos medievales y Camino de Santiago</b><br>↓<br><b>Cantar del Mio Cid</b><br>↓<br><b>Reyes Católicos y 1492</b>"}, {"type": "quiz", "kicker": "Comprueba el orden", "h": "¿Qué etapa va primero?", "q": "Si ordenamos la historia de España de más antigua a más reciente, ¿cuál de estas etapas ocurrió primero?", "opts": [{"t": "La Hispania romana", "ok": true}, {"t": "Los Reyes Católicos y el año 1492", "ok": false}, {"t": "El Cantar del Mio Cid", "ok": false}, {"t": "Los reinos medievales y el Camino de Santiago", "ok": false}], "okMsg": "¡Correcto! Roma llegó a Hispania siglos antes que los demás periodos. Tu línea de tiempo empieza justo ahí.", "noMsg": "Casi... Roma fue la civilización más antigua de las cuatro. Repasa el orden antes de empezar tu línea de tiempo."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Crea tu línea de tiempo", "body": "Ha llegado el momento de empezar tu proyecto final. En una cartulina, folio largo o documento digital, dibuja una línea horizontal y marca sobre ella las grandes etapas de la historia de España que hemos estudiado este curso.", "prompt": "Dibuja tu línea de tiempo con, al menos, estas 4 etapas en orden: 1) Hispania romana, 2) Reinos medievales y Camino de Santiago, 3) Cantar del Mio Cid, 4) Reyes Católicos y 1492. Para cada una, añade la fecha aproximada, un dibujo sencillo y una frase que la explique."}]},
  "p4:Jul:2": {"title": "Mi ensayo: España contada por mí", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 2", "h": "¿Qué te ha contado España este año?", "scenario": "Tu línea de tiempo ya está lista y cuelga en la pared de tu habitación. Ahora te toca convertir todo lo que sabes en palabras.", "body": "Esta semana escribirás un <b>ensayo de dos páginas</b> titulado 'Lo que aprendí sobre la historia y la geografía de España'. Un ensayo no es un examen: es tu oportunidad de <b>contar con tus propias palabras</b> lo que más te ha sorprendido, gustado o hecho pensar de este curso."}, {"type": "theory", "kicker": "Las partes de un buen ensayo", "h": "Introducción, desarrollo y conclusión", "body": "Todo buen ensayo tiene tres partes. La <b>introducción</b> presenta el tema (por ejemplo, qué vas a contar sobre España). El <b>desarrollo</b> explica tus ideas con ejemplos concretos: puedes hablar del relieve y los ríos, de los reinos medievales, del Cantar del Mio Cid o de los Reyes Católicos. La <b>conclusión</b> resume lo más importante y añade tu opinión personal. Recuerda argumentar tus ideas: no basta con decir 'me gustó', hay que explicar <b>por qué</b>.", "diagram": "<b>Introducción</b><br>Presento el tema<br>↓<br><b>Desarrollo</b><br>Explico con ejemplos (historia + geografía)<br>↓<br><b>Conclusión</b><br>Resumo y doy mi opinión"}, {"type": "quiz", "kicker": "Comprueba la estructura", "h": "¿Dónde va tu opinión personal?", "q": "En un ensayo bien organizado, ¿en qué parte es más adecuado añadir tu opinión personal y tu resumen final?", "opts": [{"t": "En la conclusión", "ok": true}, {"t": "Solo en el título", "ok": false}, {"t": "En la introducción", "ok": false}, {"t": "No se debe incluir la opinión en un ensayo", "ok": false}], "okMsg": "¡Exacto! La conclusión es el lugar perfecto para resumir tus ideas y compartir tu opinión.", "noMsg": "No exactamente. La opinión personal y el resumen final funcionan mejor en la conclusión, al terminar de explicar tus ideas."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu ensayo", "body": "Usa tu línea de tiempo de la semana pasada como fuente de ideas y escribe tu ensayo de dos páginas.", "prompt": "Escribe un ensayo de 2 páginas titulado 'Lo que aprendí sobre la historia y la geografía de España'. Incluye una introducción, un desarrollo con al menos tres ejemplos (dos de historia y uno de geografía, o viceversa) y una conclusión con tu opinión personal."}]},
  "p4:Jul:3": {"title": "¡A escena! Mi presentación de España", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 3", "h": "¿Te atreves a subir al escenario?", "scenario": "Tu ensayo está terminado. Ahora imagina que toda la clase, tu familia y tu profesor te escuchan durante siete minutos mientras cuentas lo que sabes de España.", "body": "Esta semana prepararás tu <b>presentación oral de 7 minutos</b>. Tendrás que elegir <b>3 eventos históricos</b> y <b>2 elementos geográficos</b> de España que te parezcan más interesantes, y explicarlos en voz alta con seguridad y claridad."}, {"type": "theory", "kicker": "Hablar en público sin miedo", "h": "Trucos para una gran presentación", "body": "Una buena presentación oral se apoya en tres claves: <b>preparación</b> (saber bien de qué vas a hablar), <b>estructura</b> (empezar con una introducción breve, desarrollar tus 5 puntos y terminar con una conclusión) y <b>voz y gestos</b> (hablar despacio, mirar al público y usar las manos para apoyar lo que dices). Puedes apoyarte en tu línea de tiempo o en dibujos de mapas para hacerlo más visual.", "diagram": "<b>3 eventos históricos</b><br>(ej. Hispania romana, Cantar del Mio Cid, 1492)<br>+<br><b>2 elementos geográficos</b><br>(ej. relieve, ríos)<br>=<br><b>Presentación de 7 minutos</b>"}, {"type": "quiz", "kicker": "Comprueba la preparación", "h": "¿Cuántos elementos debe incluir tu presentación?", "q": "Según el proyecto final, ¿qué debe incluir tu presentación oral de 7 minutos?", "opts": [{"t": "3 eventos históricos y 2 elementos geográficos", "ok": true}, {"t": "Solo 5 eventos históricos", "ok": false}, {"t": "2 eventos históricos y 3 elementos geográficos", "ok": false}, {"t": "1 evento histórico y 1 elemento geográfico", "ok": false}], "okMsg": "¡Correcto! 3 eventos históricos + 2 elementos geográficos es la combinación perfecta para tus 7 minutos.", "noMsg": "No es esa la combinación. Recuerda: son 3 eventos históricos y 2 elementos geográficos."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Prepara y ensaya tu presentación", "body": "Elige los eventos y elementos que más te gusten, escribe un pequeño guion y practica en voz alta delante de un espejo o de tu familia.", "prompt": "Prepara una presentación oral de 7 minutos con 3 eventos históricos (por ejemplo, Hispania romana, el Camino de Santiago o los Reyes Católicos) y 2 elementos geográficos (por ejemplo, el relieve o los ríos de España). Ensáyala en voz alta al menos dos veces antes de presentarla."}]},
  "p4:Jul:4": {"title": "Gracias, España: cierre de un gran curso", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 4", "h": "¿Qué ha cambiado en ti este curso?", "scenario": "Línea de tiempo, ensayo y presentación oral: ¡lo has conseguido! Solo queda una última parada antes de cerrar el curso: mirar hacia atrás y ver cuánto has crecido.", "body": "Esta semana toca <b>reflexionar</b>: ¿qué ha cambiado en tu visión de España después de todo un año estudiando su historia y su geografía? Hemos recorrido juntos la Hispania romana, el relieve y los ríos, los reinos medievales y el Camino de Santiago, el Cantar del Mio Cid, los Reyes Católicos y 1492, la población y las ciudades, y los géneros literarios."}, {"type": "theory", "kicker": "La memoria como regalo", "h": "Recordar para entender el presente", "body": "La Biblia nos enseña en <b>Deuteronomio 32:7</b>: 'Acuérdate de los días del pasado; considera los años de muchas generaciones.' Recordar la historia no es solo aprender fechas: es entender de dónde viene un pueblo para saber quiénes somos hoy. Este curso has aprendido a mirar España con otros ojos, viendo cómo cada etapa —romana, medieval, de los Reyes Católicos— dejó su huella en el país que existe ahora.", "diagram": "<b>Todo el curso en una mirada</b><br>Hispania romana → Relieve y ríos<br>Reinos medievales → Camino de Santiago<br>Cantar del Mio Cid → Reyes Católicos y 1492<br>Población y ciudades → Géneros literarios<br>↓<br>'Acuérdate de los días del pasado' (Deut 32:7)"}, {"type": "quiz", "kicker": "El versículo del cierre", "h": "¿Qué nos pide recordar Deuteronomio 32:7?", "q": "Según Deuteronomio 32:7, ¿qué se nos anima a hacer con el pasado?", "opts": [{"t": "Acordarnos de él y considerar los años de generaciones anteriores", "ok": true}, {"t": "Olvidarlo por completo para mirar solo al futuro", "ok": false}, {"t": "Repetirlo exactamente igual", "ok": false}, {"t": "Ignorarlo porque ya no importa", "ok": false}], "okMsg": "¡Así es! Deuteronomio 32:7 nos invita a recordar y valorar el pasado, tal como has hecho todo este curso.", "noMsg": "Repasa el versículo: nos anima a acordarnos del pasado y considerar los años de generaciones anteriores, no a olvidarlo."}, {"type": "reflect", "kicker": "Cierre del curso", "h": "Tu reflexión final", "body": "Termina tu proyecto final con una reflexión escrita. Da las gracias por lo aprendido y comparte cómo ha cambiado tu forma de ver España.", "prompt": "Escribe una reflexión breve respondiendo: ¿qué ha cambiado en tu visión de España después de este año? Menciona al menos dos cosas que antes no sabías y que ahora forman parte de cómo entiendes tu país. Termina con una frase de agradecimiento por todo lo aprendido este curso, inspirada en Deuteronomio 32:7: 'Acuérdate de los días del pasado; considera los años de muchas generaciones.'"}]},
});
